// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }
    function testFuzz_property(uint256 times) public {
        times = bound(times, 1, 3);
        BankLike h = new BankLike();
        for (uint256 i = 0; i < times; i++) {
            try h.drip(c) {} catch {}
        }
        assertTrue(c.tokenBalance(address(h)) == 20);
    }
}

contract BankLike {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function drip(ModifierEntrancy c) external {
        c.airDrop();
    }
}
